// Generates docs/RULES.md (English) and docs/RULES.tr.md (Turkish) from the built-in rule
// catalogue (the same data as `devgu rules explain`). Do not edit the output by hand.
import { writeFile } from "node:fs/promises";
import { ruleCatalog } from "../packages/core/dist/index.js";
import { loc } from "../packages/shared/dist/index.js";

const rules = ruleCatalog();

const CHROME = {
  en: {
    file: "../docs/RULES.md",
    heading: "DEVGU rule catalogue",
    intro:
      "Generated by `npm run docs:rules`. Do not edit by hand. Every rule lists what it cannot detect.",
    columns: "| Rule | Severity | Confidence | Engine | Name |",
    category: "Category",
    severity: "Default severity",
    confidence: "Default confidence",
    remediation: "Remediation",
    limitations: "Limitations",
    references: "References",
  },
  tr: {
    file: "../docs/RULES.tr.md",
    heading: "DEVGU kural kataloğu",
    intro:
      "`npm run docs:rules` ile üretilir. Elle düzenlemeyin. Her kural, neyi tespit edemeyeceğini listeler.",
    columns: "| Kural | Şiddet | Güven | Motor | Ad |",
    category: "Kategori",
    severity: "Varsayılan şiddet",
    confidence: "Varsayılan güven",
    remediation: "Çözüm",
    limitations: "Sınırlamalar",
    references: "Kaynaklar",
  },
};

for (const [lang, c] of Object.entries(CHROME)) {
  const out = [
    `# ${c.heading}`,
    "",
    c.intro,
    "",
    c.columns,
    "|---|---|---|---|---|",
    ...rules.map(
      (r) =>
        `| [${r.id}](#${r.id.toLowerCase()}) | ${r.severity} | ${r.confidence} | ${r.engine} | ${loc(r.name, lang)} |`,
    ),
    "",
  ];
  for (const r of rules) {
    out.push(`## ${r.id}`, "", `**${loc(r.name, lang)}**`, "", loc(r.description, lang), "");
    out.push(
      `- ${c.category}: ${r.category}`,
      `- ${c.severity}: ${r.severity}`,
      `- ${c.confidence}: ${r.confidence}`,
      "",
    );
    out.push(
      `**${c.remediation}:** ${loc(r.remediation, lang)}`,
      "",
      `**${c.limitations}:** ${loc(r.limitations, lang)}`,
      "",
    );
    if (r.references.length)
      out.push(`${c.references}:`, "", ...r.references.map((x) => `- ${x}`), "");
  }
  await writeFile(new URL(c.file, import.meta.url), out.join("\n"));
  console.log(`Wrote ${c.file.replace("../", "")} (${rules.length} rules)`);
}
